#!/usr/bin/env bash

set -euo pipefail

script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
android_root="$(cd -- "${script_dir}/../../.." && pwd)"
vendor_root="${1:-${android_root}/vendor/alps/g81}"

mkdir -p -- "${vendor_root}"

cat > "${vendor_root}/BoardConfigVendor.mk" <<'EOF'
# Generated by device/alps/g81/setup-makefiles.sh.
TARGET_PREBUILT_KERNEL := vendor/alps/g81/proprietary/kernel
BOARD_PREBUILT_VENDORIMAGE := vendor/alps/g81/proprietary/vendor.img
EOF

cat > "${vendor_root}/g81-vendor.mk" <<'EOF'
# Generated by device/alps/g81/setup-makefiles.sh.
LOCAL_PATH := vendor/alps/g81

PRODUCT_COPY_FILES += \
    $(call find-copy-subdir-files,*,vendor/alps/g81/proprietary/system/lib,system/lib)

ifneq ($(wildcard vendor/alps/g81/factory/WriteIMEI/WriteIMEI.apk),)
PRODUCT_PACKAGES += \
    G81SecretCodeRouter \
    WriteIMEI
endif
EOF

echo "Vendor makefiles written to ${vendor_root}"
